/**
 * Unit tests for org.apache.commons.lang3.StringUtils.join(Object[], char, int, int)
 */
public class StringUtils_join_TriageGen1Test {









    @Test
    public void testJoin_WithNullElements() {
        Object[] array = {"A", null, "C", null};
        // The logic: if (array[i] != null) buf.append(array[i]);
        // This means nulls are skipped in the output but the separator is still appended for the index.
        // For index 1 (null): i=1, i>startIndex(0) is true, append ',', append nothing because null.
        // For index 2 ("C"): i=2, i>startIndex(0) is true, append ',', append "C".
        // For index 3 (null): i=3, i>startIndex(0) is true, append ',', append nothing because null.
        // Expected: "A,,C,"
        assertEquals("Should handle null elements by skipping their content but keeping separators", 
            "A,,C,", StringUtils.join(array, ',', 0, 4));
    }








}

